#!/usr/bin/env python3
"""Merge multiple JSON config files left to right.

Rules:
  - Objects merge recursively.
  - Scalars and arrays are replaced by later files (default), or
    concatenated when --array-mode append is given.
  - A key explicitly set to null in a later file deletes it from the result.

Prints the merged document with sorted keys.
"""

import argparse
import json
import sys
from typing import Any

DELETED = object()  # sentinel for explicit null deletion


def _merge(base: Any, overlay: Any, array_mode: str) -> Any:
    if isinstance(overlay, dict):
        # Start from a copy so deletions don't mutate the input files' data.
        result = dict(base) if isinstance(base, dict) else {}
        for key, value in overlay.items():
            if value is None:
                result.pop(key, None)  # explicit deletion
            elif key in result:
                merged = _merge(result[key], value, array_mode)
                if merged is not DELETED:
                    result[key] = merged
            else:
                result[key] = value
        return result
    if isinstance(overlay, list):
        if array_mode == "append" and isinstance(base, list) and base:
            return base + overlay
        return overlay
    return overlay


def merge(docs: list[Any], array_mode: str = "replace") -> Any:
    """Merge a left-to-right sequence of parsed JSON documents."""
    if not docs:
        raise ValueError("need at least one document")
    result: Any = docs[0]
    for doc in docs[1:]:
        merged = _merge(result, doc, array_mode)
        if merged is DELETED:
            raise ValueError("cannot delete the entire root document")
        result = merged
    return result


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("files", nargs="+", metavar="FILE",
                        help="JSON config files, merged left to right")
    parser.add_argument("--array-mode", choices=("replace", "append"),
                        default="replace",
                        help="how arrays combine (default: replace)")
    args = parser.parse_args(argv)

    docs = []
    try:
        for path in args.files:
            with open(path, "r", encoding="utf-8") as fh:
                docs.append(json.load(fh))
    except (OSError, json.JSONDecodeError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    print(json.dumps(merge(docs, args.array_mode), indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())

import json

import pytest

from cfgmerge import merge


def load(name):
    with open(name, encoding="utf-8") as fh:
        return json.load(fh)


@pytest.fixture
def base():
    return load("tests/fixtures/base.json")


@pytest.fixture
def staging():
    return load("tests/fixtures/staging.json")


@pytest.fixture
def local():
    return load("tests/fixtures/local.json")


def test_override_scalars_and_nested_objects(base, staging):
    """Later files override scalars; objects merge recursively."""
    result = merge([base, staging])
    assert result == {
        "app": {
            "name": "service",          # untouched from base
            "debug": True,              # overridden by staging
            "log_level": "DEBUG",       # overridden by staging
        },
        "database": {                   # merged recursively
            "host": "db.internal",
            "port": 5433,
            "pool_size": 20,
        },
        "features": {"cache": False, "metrics": True},
    }


def test_deletion_via_null(base, staging, local):
    """A key explicitly set to null in a later file is deleted."""
    result = merge([base, staging, local])
    # "experimental" existed in base+staging and is deleted by local's null.
    assert "experimental" not in result["features"]
    assert result == {
        "app": {"name": "service", "debug": False, "log_level": "INFO"},
        "database": {"host": "localhost", "port": 5432,
                     "password": "secret"},
        "features": {"cache": False, "metrics": True},
    }


def test_merge_three_levels_deep():
    """Objects nested three levels deep merge recursively at every level."""
    l1 = {"a": {"b": {"c": 1, "d": 2}, "e": 3}, "top": "l1"}
    l2 = {"a": {"b": {"c": 10, "f": 11}}, "top": "l2"}
    l3 = {"a": {"b": {"d": None, "g": {"h": 20}}}}
    assert merge([l1, l2, l3]) == {
        "a": {
            "b": {"c": 10, "f": 11, "g": {"h": 20}},  # d deleted via null
            "e": 3,
        },
        "top": "l2",
    }


def test_array_mode_replace_is_default(base, staging, local):
    """Default: later arrays replace earlier ones entirely."""
    result = merge([base, staging, local])
    assert result["database"]["replicas"] == ["replica-3"]


def test_array_mode_append(base, staging, local):
    """--array-mode append: arrays concatenate left to right."""
    result = merge(
        [base, staging, local],
        array_mode="append",
    )
    assert result["database"]["replicas"] == [
        "replica-1", "replica-2", "replica-2b", "replica-3",
    ]
    assert result["allowed_hosts"] == [
        "example.com", "api.example.com", "admin.example.com",
    ]

